		CASE WHEN @SortOrder = 'descend' AND @SortField = 'materialLotId' THEN r.[MaterialLotId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'materialLotName' THEN r.[MaterialLotName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'materialLotName' THEN r.[MaterialLotName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'onHandQuantity' THEN r.[OnHandQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'onHandQuantity' THEN r.[OnHandQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'reservedQuantity' THEN r.[ReservedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'reservedQuantity' THEN r.[ReservedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'availableQuantity' THEN r.[AvailableQuantity] END ASC,
